from pathlib import Path
import base64, zlib, hashlib

path = Path('index.html')
s = path.read_text(encoding='utf-8')

def dec(blob):
    return zlib.decompress(base64.b64decode(blob)).decode('utf-8')

def replace_between(src, start, end, blob):
    i = src.find(start)
    if i < 0:
        raise SystemExit(f'missing start anchor: {start!r}')
    j = src.find(end, i)
    if j < 0:
        raise SystemExit(f'missing end anchor: {end!r}')
    return src[:i] + dec(blob) + src[j:]

CSS = ''''''
ANITA = ''''''
EDITOR = ''''''
PRESSFUN = ''''''

s = replace_between(s, '.press .plate-pair{', '/* ---- the body, in columns ---- */', CSS)
s = replace_between(s, '  { slug:"anita-wong"', '  { slug:"siddharth"', ANITA)
s = replace_between(s, 'const partsOf = host =>', 'function showCode(){', EDITOR)
s = replace_between(s, 'function plateHTML(p){', "window.addEventListener('resize'", PRESSFUN)

path.write_text(s, encoding='utf-8')
h = hashlib.sha256(path.read_bytes()).hexdigest()
print('sha256', h)
print('expected', '52e97572ce42937614d1caa1bfd2d815513ee61da11255301d979dd7516ba333')
if h != '52e97572ce42937614d1caa1bfd2d815513ee61da11255301d979dd7516ba333':
    raise SystemExit('patched file does not yet exactly match uploaded index.html')
print('exact match')
